from pathlib import Path
import re, json

ROOT=Path(__file__).resolve().parents[1]
def read(path): return (ROOT/path).read_text(encoding='utf-8')
def write(path,text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def replace_once(path,old,new):
    text=read(path); count=text.count(old)
    if count!=1: raise SystemExit(f'{path}: expected one match, found {count}: {old[:120]!r}')
    write(path,text.replace(old,new,1))
def regex_once(path,pattern,replacement,flags=0):
    text=read(path); out,count=re.subn(pattern,lambda _m:replacement,text,count=1,flags=flags)
    if count!=1: raise SystemExit(f'{path}: expected one regex match, found {count}: {pattern[:140]!r}')
    write(path,out)

