# Packet microscope: use actual seeded IPv6 addresses instead of its old hard-coded pair.
packet='src/packet/model.ts'
replace_once(packet,"  sourceIpv4?: string;\n  destinationIpv4?: string;", "  sourceIpv4?: string;\n  destinationIpv4?: string;\n  sourceIpv6?: string;\n  destinationIpv6?: string;")
insert_parser=r'''function parseIpv6(value: string | undefined, fallback: readonly number[]): number[] {
  if (!value) return [...fallback];
  try {
    const normalized=value.trim().toLowerCase();
    if(!normalized||normalized.includes('%')||normalized.includes('.')||(normalized.match(/::/g)??[]).length>1)return[...fallback];
    const compressed=normalized.includes('::');
    const [leftText,rightText='']=compressed?normalized.split('::'):[normalized,''];
    const side=(text:string)=>text===''?[]:text.split(':').map((part)=>{if(!/^[0-9a-f]{1,4}$/.test(part))throw new Error('bad');return Number.parseInt(part,16);});
    const left=side(leftText),right=side(rightText);
    const groups=compressed?[...left,...Array.from({length:8-left.length-right.length},()=>0),...right]:left;
    if(groups.length!==8||(compressed&&8-left.length-right.length<1))return[...fallback];
    return groups.flatMap((group)=>[(group>>>8)&0xff,group&0xff]);
  } catch { return [...fallback]; }
}
'''
replace_once(packet,"export function hex16(value: number): string {", insert_parser+"export function hex16(value: number): string {")
replace_once(packet,"function buildIpv6(config: PacketConfig, transportLength: number): { bytes: number[]; checksum: null; fields: PacketField[] } {", "function buildIpv6(config: PacketConfig, transportLength: number, source: readonly number[], destination: readonly number[]): { bytes: number[]; checksum: null; fields: PacketField[] } {")
replace_once(packet,"  const bytes = [0x60,0,0,0,...word16(payloadLength),nextHeader,config.ttl,...SOURCE_IPV6,...DEST_IPV6];", "  const bytes = [0x60,0,0,0,...word16(payloadLength),nextHeader,config.ttl,...source,...destination];")
replace_once(packet,"    { id: 'ip6-src', label: 'Source', value: formatIpv6(SOURCE_IPV6), offset: 8, length: 16 },\n    { id: 'ip6-dst', label: 'Destination', value: formatIpv6(DEST_IPV6), offset: 24, length: 16 },", "    { id: 'ip6-src', label: 'Source', value: formatIpv6(source), offset: 8, length: 16 },\n    { id: 'ip6-dst', label: 'Destination', value: formatIpv6(destination), offset: 24, length: 16 },")
replace_once(packet,"function pseudoHeader(config: PacketConfig, transportLength: number, sourceIpv4: readonly number[], destinationIpv4: readonly number[]): number[] {", "function pseudoHeader(config: PacketConfig, transportLength: number, sourceIpv4: readonly number[], destinationIpv4: readonly number[], sourceIpv6: readonly number[], destinationIpv6: readonly number[]): number[] {")
replace_once(packet,"  return [...SOURCE_IPV6,...DEST_IPV6,...word32(transportLength + config.payloadBytes),0,0,0,protocol];", "  return [...sourceIpv6,...destinationIpv6,...word32(transportLength + config.payloadBytes),0,0,0,protocol];")
replace_once(packet,"function buildTransport(config: PacketConfig, payload: readonly number[], sourceIpv4: readonly number[], destinationIpv4: readonly number[]): { bytes: number[]; checksum: number; fields: PacketField[] } {", "function buildTransport(config: PacketConfig, payload: readonly number[], sourceIpv4: readonly number[], destinationIpv4: readonly number[], sourceIpv6: readonly number[], destinationIpv6: readonly number[]): { bytes: number[]; checksum: number; fields: PacketField[] } {")
replace_once(packet,"const checksumInput = config.family === 'ipv4' ? [...bytes, ...payload] : [...pseudoHeader(config, 8, sourceIpv4, destinationIpv4), ...bytes, ...payload];", "const checksumInput = config.family === 'ipv4' ? [...bytes, ...payload] : [...pseudoHeader(config, 8, sourceIpv4, destinationIpv4, sourceIpv6, destinationIpv6), ...bytes, ...payload];")
replace_once(packet,"let checksum = checksum16([...pseudoHeader(config, transportLength, sourceIpv4, destinationIpv4), ...bytes, ...payload]);", "let checksum = checksum16([...pseudoHeader(config, transportLength, sourceIpv4, destinationIpv4, sourceIpv6, destinationIpv6), ...bytes, ...payload]);")
replace_once(packet,"  const destinationIpv4 = parseIpv4(config.destinationIpv4, DEFAULT_DEST_IPV4);\n  const ethernet = buildEthernet(config);\n  const network = config.family === 'ipv4' ? buildIpv4(config, transportHeaderLength, sourceIpv4, destinationIpv4) : buildIpv6(config, transportHeaderLength);\n  const transport = buildTransport(config, payload, sourceIpv4, destinationIpv4);", "  const destinationIpv4 = parseIpv4(config.destinationIpv4, DEFAULT_DEST_IPV4);\n  const sourceIpv6 = parseIpv6(config.sourceIpv6, SOURCE_IPV6);\n  const destinationIpv6 = parseIpv6(config.destinationIpv6, DEST_IPV6);\n  const ethernet = buildEthernet(config);\n  const network = config.family === 'ipv4' ? buildIpv4(config, transportHeaderLength, sourceIpv4, destinationIpv4) : buildIpv6(config, transportHeaderLength, sourceIpv6, destinationIpv6);\n  const transport = buildTransport(config, payload, sourceIpv4, destinationIpv4, sourceIpv6, destinationIpv6);")

